import React, { useState, useEffect, useRef } from "react";
import { Link } from "react-router-dom";
import "./Navbar.css";

const Navbar = () => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false); // Estado para la hamburguesa
  const menuRef = useRef(null); // Usamos un ref para acceder al menú y detectar clics fuera de él

  // Detectar scroll para mostrar la navbar fija después del Home
  useEffect(() => {
    const handleScroll = () => {
      if (window.scrollY > window.innerHeight * 0.9) {
        setIsScrolled(true);
      } else {
        setIsScrolled(false);
      }
    };

    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  // Detectar clic fuera del menú para cerrarlo
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setIsMenuOpen(false); // Cerrar el menú si el clic fue fuera
      }
    };

    // Agregar el evento de clic para cerrar el menú
    document.addEventListener("click", handleClickOutside);

    // Limpiar el evento cuando el componente se desmonte
    return () => {
      document.removeEventListener("click", handleClickOutside);
    };
  }, []);

  // Cierra el menú después de hacer clic en un enlace
  const handleLinkClick = () => {
    setIsMenuOpen(false); // Cambiar el estado para cerrar el menú
  };

  // Cerrar el menú cuando se hace clic en el ícono de la hamburguesa (X)
  const handleMenuToggle = () => {
    setIsMenuOpen(!isMenuOpen); // Alternar el estado del menú
  };

  return (
    <>
      {/* Navbar inicial fusionada con Home */}
      <nav className="navbar navbar-top">
        <div className="navbar-container">
          {/* Icono de menú hamburguesa en móvil */}
          <div className="menu-icon" onClick={handleMenuToggle}>
            <i className={`fa ${isMenuOpen ? "fa-times" : "fa-bars"}`}></i>
          </div>
          <h1 className="logo">
            <Link to="/"><span className="trader">FREE</span> TRADER</Link>
          </h1>
          <ul className={`nav-links ${isMenuOpen ? "open" : ""}`} ref={menuRef}>
            <li><Link to="/" onClick={handleLinkClick}>Inicio</Link></li>
            <li><Link to="/cursos" onClick={handleLinkClick}>Cursos</Link></li>
            <li><Link to="/sobre-nosotros" onClick={handleLinkClick}>Sobre Nosotros</Link></li>
          </ul>
        </div>
      </nav>

      {/* Navbar fija que aparece después del Home */}
      <nav className={`navbar navbar-fixed ${isScrolled ? "visible" : ""}`}>
        <div className="navbar-container">
          {/* Icono de menú hamburguesa en móvil */}
          <div className="menu-icon" onClick={handleMenuToggle}>
            <i className={`fa ${isMenuOpen ? "fa-times" : "fa-bars"}`}></i>
          </div>
          <h1 className="logo">
            <Link to="/"><span className="trader">FREE</span> TRADER</Link>
          </h1>
          <ul className={`nav-links ${isMenuOpen ? "open" : ""}`} ref={menuRef}>
            <li><Link to="/" onClick={handleLinkClick}>Inicio</Link></li>
            <li><Link to="/cursos" onClick={handleLinkClick}>Cursos</Link></li>
            <li><Link to="/sobre-nosotros" onClick={handleLinkClick}>Sobre Nosotros</Link></li>
          </ul>
        </div>
      </nav>
    </>
  );
};

export default Navbar;
